//
//  GeoMath.swift
//  SatTracker
//
//  The single place where geographic coordinates become scene coordinates.
//
//  Frame convention (the whole app depends on it):
//
//      (lat 0°, lon 0°)    → (1, 0, 0)      equator / prime meridian
//      lat +90°            → (0, 1, 0)      north pole
//      (lat 0°, lon +90°)  → (0, 0, −1)     equator / 90° east
//
//  so that
//
//      x =  r·cos(lat)·cos(lon)
//      y =  r·sin(lat)
//      z = −r·cos(lat)·sin(lon)
//
//  The Earth mesh is generated by `EarthNode` with matching UVs
//  (u = (lon + 180)/360, v = (lat + 90)/180), which makes the texture mapping
//  exact rather than calibrated by eye. `longitudeOffset` is kept as the single
//  place a correction would go if the mesh convention ever changed; it is 0.
//

import Foundation
import SatelliteKit
import simd

enum GeoMath {

    /// Rotational offset between the texture's prime meridian and the frame's.
    /// Zero because `EarthNode` builds its own UV sphere from this convention.
    static let longitudeOffset: Double = 0

    /// Mean Earth radius used for the scene's unit sphere, matching the
    /// equatorial radius SatelliteKit uses for `a₀` and altitude.
    static let earthRadiusKm: Double = EarthConstants.Rₑ

    // MARK: - Conversions

    /// Unit vector on the sphere for a geodetic coordinate.
    @inlinable
    static func unitVector(lat: Double, lon: Double) -> SIMD3<Float> {
        let latR = (lat * .pi / 180)
        let lonR = ((lon + longitudeOffset) * .pi / 180)
        let c = cos(latR)
        return SIMD3<Float>(Float(c * cos(lonR)),
                            Float(sin(latR)),
                            Float(-c * sin(lonR)))
    }

    /// Position in scene units (1 = one Earth radius) for a geodetic coordinate.
    @inlinable
    static func scenePosition(lat: Double, lon: Double, altKm: Double) -> SIMD3<Float> {
        let r = Float(1 + altKm / earthRadiusKm)
        return unitVector(lat: lat, lon: lon) * r
    }

    /// Position on a shell of the given scene radius.
    @inlinable
    static func scenePosition(lat: Double, lon: Double, radius: Float) -> SIMD3<Float> {
        unitVector(lat: lat, lon: lon) * radius
    }

    /// Position for a SatelliteKit geodetic triple.
    @inlinable
    static func scenePosition(_ lla: LatLonAlt) -> SIMD3<Float> {
        scenePosition(lat: lla.lat, lon: lla.lon, altKm: lla.alt)
    }

    /// Inverse of `unitVector`, in degrees.
    static func latLon(from unit: SIMD3<Float>) -> (lat: Double, lon: Double) {
        let n = simd_normalize(unit)
        let lat = Double(asin(max(-1, min(1, n.y)))) * 180 / .pi
        let lon = Double(atan2(-n.z, n.x)) * 180 / .pi
        return (lat, lon)
    }

    // MARK: - Ground tracks

    /// Split a lat/lon polyline wherever it jumps across the antimeridian.
    ///
    /// A ground track that wraps from +179° to −179° would otherwise draw a
    /// line all the way around the planet.
    static func splitAtAntimeridian(_ points: [LatLonAlt]) -> [[LatLonAlt]] {
        guard !points.isEmpty else { return [] }

        var runs: [[LatLonAlt]] = []
        var current: [LatLonAlt] = [points[0]]

        for point in points.dropFirst() {
            if let previous = current.last, abs(point.lon - previous.lon) > 180 {
                runs.append(current)
                current = [point]
            } else {
                current.append(point)
            }
        }
        runs.append(current)
        return runs.filter { $0.count > 1 }
    }

    // MARK: - Angles

    /// Great-circle distance in kilometres between two geodetic points.
    static func greatCircleKm(lat1: Double, lon1: Double, lat2: Double, lon2: Double) -> Double {
        let φ1 = lat1 * .pi / 180, φ2 = lat2 * .pi / 180
        let Δφ = (lat2 - lat1) * .pi / 180
        let Δλ = (lon2 - lon1) * .pi / 180
        let a = sin(Δφ / 2) * sin(Δφ / 2) + cos(φ1) * cos(φ2) * sin(Δλ / 2) * sin(Δλ / 2)
        return 2 * earthRadiusKm * atan2(a.squareRoot(), (1 - a).squareRoot())
    }

    /// Normalise an angle in degrees into [−180, 180).
    static func wrapLongitude(_ lon: Double) -> Double {
        var value = lon.truncatingRemainder(dividingBy: 360)
        if value >= 180 { value -= 360 }
        if value < -180 { value += 360 }
        return value
    }

    /// Interpolate between two scene positions on the unit sphere rather than
    /// through it, so fast movers sweep along their arc instead of cutting a chord.
    @inlinable
    static func slerp(_ a: SIMD3<Float>, _ b: SIMD3<Float>, _ t: Float) -> SIMD3<Float> {
        let ra = simd_length(a), rb = simd_length(b)
        guard ra > 0, rb > 0 else { return a }
        let na = a / ra, nb = b / rb
        let dot = max(-1, min(1, simd_dot(na, nb)))
        let omega = acos(dot)
        let r = ra + (rb - ra) * t
        if omega < 1e-4 { return (na + (nb - na) * t) * r }
        let s = sin(omega)
        let wa = sin((1 - t) * omega) / s
        let wb = sin(t * omega) / s
        return (na * wa + nb * wb) * r
    }
}
